/* Conditions extracted verbatim from https://datracker.strathfield.nsw.gov.au/document/download?key=cWMAue07lcI=&fileName=DA2025.23 - 8-10 Exeter Road HOMEBUSH WEST - Notice of Determination (Signed).PDF (conditions-extractor-2026-08-16) — export-conditions-2026-08-16. Do not hand-edit. */
registerRefData('nsw-cond-n-2401',{"id":2401,"pan":null,"ref":"10.2025.23.1","address":"8-10 Exeter Rd, Homebush West 2140 NSW","description":"Demolition works and adaptive re-use of existing heritage dwelling including alterations and additions and construction of a new two storey building and use of the site as a co-living housing development comprising of 15 private rooms with a maximum occupancy of 16 persons.","outcome":"approved","outcome_raw":"Approved - Local Planning Panel","outcome_source":"tracker","determined":"2025-07-21","notice_url":"https://datracker.strathfield.nsw.gov.au/document/download?key=cWMAue07lcI=&fileName=DA2025.23 - 8-10 Exeter Road HOMEBUSH WEST - Notice of Determination (Signed).PDF","sha256":"e2a2b01b85643c9084349cd2ecdf8d4471de5c4ae0088a52dd1892a9619373cc","pages":28,"layout":"numbered","n":65,"fetched_at":"2026-08-17T01:20:28+00:00","file":"n/2401.js","source_page":"https://datracker.strathfield.nsw.gov.au/Application/ApplicationDetails/010.2025.00000023.001","lga":"STRATHFIELD","conditions":[{"label":"1","code":null,"number":"1","title":"Compliance with Building Code of Australia and insurance requirements under Home","text":"Building Act 1989\n1. It is a condition of a development consent for development that involves building\nwork that the work must be carried out in accordance with the requirements of\nthe Building Code of Australia.\n2. It is a condition of a development consent for development that involves\nresidential building work for which a contract of insurance is required under\nthe Home Building Act 1989, Part 6 that a contract of insurance is in force before\nbuilding work authorised to be carried out by the consent commences.\n3. It is a condition of a development consent for a temporary structure used as an\nentertainment venue that the temporary structure must comply with Part B1 and\nNSW Part H102 in Volume 1 of the Building Code of Australia.\n4. In subsection (1), a reference to the Building Code of Australia is a reference to the\nBuilding Code of Australia as in force on the day on which the application for the\nconstruction certificate was made.\n5. In subsection (3), a reference to the Building Code of Australia is a reference to the\nBuilding Code of Australia as in force on the day on which the application for\ndevelopment consent was made.\n6. This section does not apply-\na. to the extent to which an exemption from a provision of the Building Code\nof Australia or a fire safety standard is in force under the Environmental\nPlanning and Assessment (Development Certification and Fire Safety)\nRegulation 2021, or\nb. to the erection of a temporary building, other than a temporary structure\nto which subsection (3) applies.","stage":"general","stage_basis":"heading","page":3},{"label":"2","code":null,"number":"2","title":"Co-living housing","text":"1. This section applies to development permitted under State Environmental Planning\nPolicy (Housing) 2021, Chapter 3, Part 3.\n2. It is a condition of the development consent that from the day on which an\noccupation certificate is issued for the development-\na. the co-living housing must be managed in accordance with a plan of\nmanagement by a managing agent who is contactable 24 hours a day, and\nb. notice of a change to the plan of management must be given to the\nconsent authority no later than 3 months after the change, and\nc. private rooms and communal living areas in the co-living housing must\ncontain appropriate furniture and fittings, maintained in a reasonable state\nof repair, for the use of residents.","stage":"general","stage_basis":"heading","page":3},{"label":"3","code":null,"number":"3","title":"Erection of signs","text":"1. This section applies to a development consent for development involving building\nwork, subdivision work or demolition work.\n2. It is a condition of the development consent that a sign must be erected in a\nprominent position on a site on which building work, subdivision work or\ndemolition work is being carried out-\na. showing the name, address and telephone number of the principal certifier\nfor the work, and\nb. showing the name of the principal contractor, if any, for the building work\nand a telephone number on which the principal contractor may be\ncontacted outside working hours, and\nc. stating that unauthorised entry to the work site is prohibited.\n3. The sign must be-\na. maintained while the building work, subdivision work or demolition work is\nbeing carried out, and\nb. removed when the work has been completed.\n4. This section does not apply in relation to-\na. building work, subdivision work or demolition work carried out inside an\nexisting building, if the work does not affect the external walls of the\nbuilding, or\nb. Crown building work certified to comply with the Building Code of Australia\nunder the Act, Part 6.","stage":"general","stage_basis":"heading","page":4},{"label":"4","code":null,"number":"4","title":"","text":"Approved plans and supporting documentation.\nApproved Plans\nDescription Reference\nNo. Date Revision Prepared By\nCover Sheet DA-000-01 26.06.25 11 Daniel Younan &\nAssociates\nSite Analysis\nPlan DA-000-02 26.06.25 11 Daniel Younan &\nAssociates\nSurvey Plan DA-000-03 11.12.24 09 Daniel Younan &\nAssociates\nExisting Ground\nFloor Plan DA-000-04 11.12.24 09 Daniel Younan &\nAssociates\nProposed\nDemolition Plan DA-000-05 11.12.24 09 Daniel Younan &\nAssociates\nProposed\nGround Floor\nPlan\nDA-100-10 26.06.25 11\nDaniel Younan &\nAssociates\nProposed Level","stage":"general","stage_basis":"heading","page":4},{"label":"1","code":null,"number":"1","title":"Floor Plan DA-100-11 26.06.25 11 Daniel Younan &","text":"Associates\nProposed Roof\nPlan DA-100-12 26.06.25 11 Daniel Younan &\nAssociates\nCut & Fill\nDiagram DA-150-02 16.05.25 10 Daniel Younan &\nAssociates\nProposed West\nElevation DA-200-00 11.12.24 09 Daniel Younan &\nAssociates\nProposed East\nElevation DA-200-01 11.12.24 09 Daniel Younan &\nAssociates\nProposed North\nElevation DA-200-02 11.12.24 09 Daniel Younan &\nAssociates\nProposed South\nElevation DA-200-03 16.12.24 10 Daniel Younan &\nAssociates\nProposed South\nElevation\n(Retained\nBuilding).\nDA-200-04 11.12.24 09\nDaniel Younan &\nAssociates\nProposed North\nElevation (New\nBuilding)\nDA-200-05 11.12.24 09\nDaniel Younan &\nAssociates\nStreetscape\nElevation\nHenely Road\nDA-200-10 11.12.24 09\nDaniel Younan &\nAssociates\nProposed\nSections A & B\nDA-300-01,\nDA-300-02 26.06.25 11 Daniel Younan &\nAssociates\nBulk Storage\nDiagram DA-500-01 16.05.25 10 Daniel Younan &\nAssociates\nExternal\nMaterials &\nFinishes\nSchedule\nDA-600-00 11.12.24 09\nDaniel Younan &\nAssociates\nStormwater\nDrainage Plan\n2511-\nS1/3,S2/3,\nS3/3\n10.06.25 C John Romanous &\nAssociates\nLandscape Plan L01, L02,\nL03\n01.11.202","stage":"general","stage_basis":"heading","page":5},{"label":"4","code":null,"number":"4","title":"B B+E Landscape","text":"Architects\nApproved Documentation\nDescription Reference\nNo.\nDate Revision Prepared By\nWaste\nManagement\nPlan\n- 20.05.25 - Daniel Younan &\nAssociates\nArbor Impact\nAssessment\n19 May 2025 2 Smart Arbor\nProfessional\nConsulting -\nArboriculture Australia\nAddendum\nStatement -\n30 May 2025 Smart Arbor\nProfessional\nArbor Impact\nAssessment\nConsulting -\nArboriculture Australia\nBuilding Code of\nAustralia Report\nPages 1 -\n20\n04 December\n2024\nDesign Right\nConsulting\nNatHERS and\nBASIX\nAssessment\n2401223 06\nDecember\n2025\nA Efficient Living\nIn the event of any inconsistency between the approved plans and documents, the\napproved plans prevail.\nIn the event of any inconsistency with the approved plans and a condition of this\nconsent, the condition prevails.","stage":"general","stage_basis":"heading","page":5},{"label":"5","code":null,"number":"5","title":"Infrastructure Development Contributions","text":"Council has identified that the development will be subject to the imposition of\nDevelopment Contributions. In accordance with Council’s relevant Contributions Plan,\nthe following monetary contributions are required.\nDEVELOPMENT CONTRIBUTIONS\nStrathfield Section 94 Development Contributions -\nRoads and Traffic Management\n$9295.27\nStrathfield Section 94 Development Contributions -\nLocal Open Space\n$22,997.18\nStrathfield Section 94 Development Contributions -\nMajor Open Space\n$67,101.60\nStrathfield Section 94 Development Contributions -\nCommunity Facilities\n$14,748.57\nStrathfield Section 94 Development Contributions -\nAdministration\n$1493.25\nTOTAL CONTRIBUTIONS $115,635.88\nIndexation\nThe above contributions will be indexed at the time of payment to reflect inflation, in\naccordance with the indices provided by the relevant Development Contributions Plan.\nIndexation will be based on the CPI of 140.9 used to calculate the above contribution\namount.\nPlease email council council@strathfield.nsw.gov.au prior to the payment of s7.11 or\ns7.12 Contributions to confirm the indexed contribution payable and the form of\npayment that will be accepted by Council.\nTiming of Payment\nThe contribution must be paid and receipted by Council prior to the issue of the\nConstruction Certificate\nA copy of the current Development Contributions Plans may be viewed on Council’s\nwebsite www.strathfield.nsw.gov.au.","stage":"general","stage_basis":"heading","page":6},{"label":"6","code":null,"number":"6","title":"Demolition Inspection Fees","text":"The owner/applicant is to arrange for Council to carry out pre-commencement and post\ndemolition inspections of the site.\ni. The pre-commencement inspection must be carried out by a Council Officer\nonce all site works required as part of this consent have been installed and prior\nto any demolition works commencing.\nii. A final, post demolition inspection must be carried out by a Council Officer once\nall demolition works have been completed to ensure that the site is left in a\nsatisfactory manner and in accordance with the conditions of consent.\niii. A total of $700 for the two (2) inspections is to be paid to Council prior to the\nissue of the construction certificate or any demolition works commencing on\nsite.\nFor booking of Inspections - The applicant/owner is to contact Council’s Customer\nService Centre (Ph 02 9748-9999) minimum two (2) working days prior to the required\ninspection.","stage":"general","stage_basis":"heading","page":7},{"label":"7","code":null,"number":"7","title":"Section 138 Roads Act 1993 & Section 68 Local Government Act 1993","text":"Unless otherwise specified by a condition of this consent, this Development Consent\ndoes not give any approval to undertake works on public infrastructure.\nSeparate approval is required under Section 138 of the Roads Act 1993 and Section 68\nof the Local Government Act 1993 for any of the following activities carried out in, on or\nover a public road (including the footpath) listed below.\nAn application is required to be lodged and approved prior to the commencement of any\nof the following works or activities.\n(a) If any excavation is to be supported by the use of below ground (cable) anchors that\nare constructed under Council’s roadways/footways.\n(b) Swinging or hoisting goods over any part of a public road by means of a lift, crane or\nthe like;\n(c) Establishing a “works zone”;\n(d) Placing or storing materials or equipment;\n(e) Placing or storing waste containers or skip bins;\n(f) Stormwater & ancillary to public infrastructure on private land\n(g) Erecting a structure or carrying out work\nBUILDING WORK","stage":"general","stage_basis":"heading","page":7},{"label":"8","code":null,"number":"8","title":"Road Opening Permit","text":"A Road Opening Permit must be obtained from Council, in the case of local or regional\nroads, or from TFNSW in the case of State roads, for every opening of a public reserve to\naccess services including sewer, stormwater drains, water mains, gas\nmains, and\ntelecommunications before the commencement of works in the road.","stage":"before_cc","stage_basis":"heading","page":8},{"label":"9","code":null,"number":"9","title":"Vehicular Crossing - Minor Development","text":"Constructing a vehicular crossing and footpath requires a separate approval under\nSection 138 of the Roads Act 1993 prior to the commencement of those works. This\napproval must be obtained from Council by completing and submitting a works permit\napplication.\nThe approval for a new or modified vehicular crossing will contain the plans and\nspecifications required to construct the crossing and footpath. These works must be\ncompleted prior to the issue of an Occupation Certificate.","stage":"before_cc","stage_basis":"heading","page":8},{"label":"10","code":null,"number":"10","title":"Tree Bond","text":"A tree bond (calculated in accordance with Council’s adopted Fees and Charges) must be\npaid to Council, prior to the issue of a Construction Certificate.\nTree number Species Name Height Bond Fee\nT10 Lophostemon confertus 11m $22,168.00\nT11 Lophostemon confertus 12m $22,168.00\nThe deposit is required as security against any damage to existing trees to be retained\non Council’s Road reserve, during works on the site. The applicant must bear the cost of\nall restoration works to Council’s property damaged during the course of this\ndevelopment.\nA sound protection barrier anchored firmly into the ground 1.8m in height x 2 metres\nclear of the base of the tree at any one point and that the fence is to extend up to the\nback of the kerb and to the edge of the footpath.\nPayment may be accepted in the form of a bank cheque, credit card or bank guarantee.\nAn administration fee applies to all bonds in accordance with Council’s adopted Fees and\nCharges.\nA request for refund of the Tree Bond must be made in writing.\nTree Bonds may be forfeited if a tree is dead, made dangerous or has been terminally\ndamaged, or will be held until tree/s have fully recovered from the construction damage\nor were replacement/planted trees have become fully established and are over 6 metres\nin height.","stage":"before_cc","stage_basis":"heading","page":8},{"label":"11","code":null,"number":"11","title":"Design amendments","text":"Prior to the Issue of a Construction Certificate, the applicant must submit amended\narchitectural plans and specifications to Council for review. These plans must\nincorporate all required amendments as specified in a) to e) below.\nThe applicant must obtain written confirmation from Council’s Director of Planning and\nEnvironment confirming that the submitted plans satisfactorily address all required\namendments.\nA copy of this written confirmation must be provided to the Certifier prior to the issue\nof the Construction Certificate.\na) The Civil Plans and Landscape Plans must be amended to align with the layout\nof the driveway, car parking configuration, and all relevant details as shown on\nthe approved Architectural Plans.\nb) All air conditioning (AC) units proposed on the upper-level western elevation\nmust be installed either directly on the floor or affixed to the solid component\nof the balcony wall in a manner that conceals the units from view from the\npublic domain.\nc) The two air conditioning units proposed on the southern elevation of the\nexisting dwelling must be designed within an enclosure integrated into the\narchitecture to obscure them from the public domain and internal entryway.\nd) Details of the proposed balcony separation screens between Co-Living Rooms\n12, 13, 14 and 15 on the Western elevation as shown on Architectural Plan DA-\n200-05 are to be supplied, the architectural plans including elevations are to be\namended accordingly.\ne) The following windows must be fitted with an external operable privacy screen\nW-1-15, W-1-14, W1-11, W1-10, W-G-15, W-G-14, W-G-11, and W-G-10 to\nmitigate overlooking to the Eastern adjoining site (8a Exter Road, Homebush).","stage":"before_cc","stage_basis":"heading","page":9},{"label":"12","code":null,"number":"12","title":"Long Service Levy","text":"Before the issue of the relevant construction certificate the long service levy of $3,452.00\nas calculated at the date of this consent, must be paid to the Long Service Corporation\nof Council under the Building and Construction industry Long Service Payments Act 1986,\nsection 34, and evidence of the payment is to be provided to the certifier.","stage":"before_cc","stage_basis":"heading","page":10},{"label":"13","code":null,"number":"13","title":"Fire Safety Measures","text":"A list of the existing and proposed essential fire safety measures that are to be provided\nin relation to the land and any building on the land as a consequence of the building\nwork must accompany an application for a construction certificate, which must b e\nsubmitted to the Principal Certifier. Such list must also specify the minimum standard of\nperformance for each essential fire safety measure included in the list.","stage":"before_cc","stage_basis":"heading","page":10},{"label":"14","code":null,"number":"14","title":"Structural Details","text":"Engineer’s details for all reinforced concrete work, structural beams, columns & other\nstructural members must be prepared by a suitably qualified practising Structural\nEngineer. These details are to be submitted to the Principal Certifier for approval.\nA copy must be forwarded to Council where Council is not the Principal Certifier.","stage":"before_cc","stage_basis":"heading","page":10},{"label":"15","code":null,"number":"15","title":"Waste Management Plan - an approved document of this consent","text":"Before the issue of a construction certificate a waste management plan for the\ndevelopment must be provided to the principal certifying authority.","stage":"before_cc","stage_basis":"heading","page":10},{"label":"16","code":null,"number":"16","title":"Waste Management Plan requirements","text":"Before the issue of a construction certificate, a waste management plan for the\ndevelopment must be prepared and provided to Council. The plan must be prepared\na. in accordance with\ni. the Environment Protection Authority’s Waste\nClassification Guidelines as in force from time to time, and\nii. a development control plan that provides for waste management that applies\nto the land on which the work or the clearing of vegetation is carried out, and\nb. include the following information-\ni. the contact details of the person removing waste,\nii. an estimate of the type and quantity of waste,\niii. whether waste is expected to be reused, recycled or sent to landfill,\niv. the address of the disposal location for waste,\nv. a litter management plan must be included in the WMP and outline that the\noccupant must take all practicable steps to ensure that the area of public\nfootpath or public area adjacent to the premises within a 50m radius is\nmaintained in a clean and tidy condition.\nA copy of the waste management plan must be kept on-site at all times while work\napproved under the development consent is being carried out.","stage":"before_cc","stage_basis":"heading","page":10},{"label":"17","code":null,"number":"17","title":"Photographic Archival Documentation (Major Works)","text":"Prior to the Construction Certificate being issued, an archival photographic recording of\nthe heritage item must be prepared to the satisfaction of Council’s Heritage Planner. The\nrecording must be in a digital form, prepared in accordance with the NSW Her itage\nDivision of the Department of Environment and Heritage guidelines titled “Photographic\nRecording of Heritage Items using Film or Digital Capture”. One copy of the record is to\nbe submitted to Council to be lodged with Council’s Archives (see - Heritage | NSW\nEnvironment and Heritage)\nThe archival documentation, and the number and type of selected enlarged photographs\nrequired will be determined by the significance and quality of the building or structure.\nFor a scope of work, refer to Council’s Heritage Planner to determine the particular\narchitectural and design features of the building or site that need to be recorded.\nAs significant fabric may remain concealed and only be exposed during construction\nworks, the archival recording must be undertaken in stages as considered appropriate\nby the conservation architect commissioned for the project.\nThe archival recordings must be submitted to the satisfaction of Council’s Heritage\nPlanner as follows:\n(a) Prior to the removal of any significant building fabric or furnishings from the site,\nprior to the commencement of any work on site and prior to a Construction\nCertificate being issued.\n(b) Significant building fabric or furnishings that are exposed during demolition or\nconstruction and after work has been completed on site prior to any Occupation\nCertificate being issued.\nThe form of recording is to be a photographic documentation of the site and its context,\nand the exteriors and interiors of the existing building(s) photographed, where\nappropriate, using a camera/lens capable of ‘perspective correction’.\n(c) For each of the archival recordings listed above in (a) and (b), the digital form of the\nrecording must be as follows:\ni. The Development Application number and the Condition of Consent number\nmust be noted.\nii. Include a summary report detailing the project description, date and authorship\nof the photographic record, method of documentation and limitations of the\nphotographic record.\niii. The electronic images are to be taken with a minimum 8 megapixel camera,\nsaved as JPEG TIFF or PDF files with a size of approximately 4 -6MB, and cross\nreferenced to the digital catalogue sheets and base plans. Choose only images\nthat are necessary to document the process, and avoid duplicate images.\niv. Include written confirmation, issued with the authority of both the applicant\nand the photographer that Strathfield Council is granted a perpetual non -\nexclusive licence to make use of the copyright in all images supplied, including\nthe right to make copies available to third parties as thought they were Council\nimages. The signatures of both the applicant and the photographer must be\nincluded.\n(d) The report can be submitted on a USB, in PDF/A format (created directly from the\ndigital original), with a digital catalogue of images with the following data for each: DOS\ntitle, image subject/description and data photograph taken.","stage":"before_cc","stage_basis":"heading","page":12},{"label":"18","code":null,"number":"18","title":"Building Works to Comply with BCA - Heritage Buildings or Buildings Within","text":"Conservation Area.\nAny building works required to ensure compliance with the BCA or new building\nstandards that are not specified in the approved plan must not damage existing fabric\nand building features. If such upgrading works will potentially impact on existing fabric\nand features, details of the works must be submitted and approved by Council’s Heritage\nPlanner prior to the issue of a Construction Certificate.","stage":"before_cc","stage_basis":"heading","page":13},{"label":"19","code":null,"number":"19","title":"Reuse of Significant Building Elements","text":"Significant building elements such as bricks, sandstone blocks, verandah thresholds, wall\nvents, ceiling roses and timber joinery must be reused and recycled. The recycling must\noccur, preferably on site or at suitable professional recycling yards specialising in the\nrecycling of historic building materials. Removal and storage of these materials must be\ncarefully carried out by the workers and a specific stockpile area must be designated and\nprotected.\nA detailed plan for execution of the above requirements must be submitted to and\napproved by Council’s Heritage Planner, prior to issue of a Construction Certificate.","stage":"before_cc","stage_basis":"heading","page":13},{"label":"20","code":null,"number":"20","title":"Basix Commitments","text":"The approved BASIX Certificate must be submitted to the Principal Certifier with the\napplication for a Construction Certificate.\nAll measures and commitments as detailed in the BASIX Certificate No. 1776504M must\nbe implemented on the plans lodged with the application for the Construction\nCertificate.","stage":"before_cc","stage_basis":"heading","page":13},{"label":"21","code":null,"number":"21","title":"Payment of security deposits","text":"Before the issue of the relevant construction certificate, the applicant must:\na) make payment of $17,510.00 for a security deposit and $155.00 for\nAdministration Fee to the consent authority, and\nb) if a principal certifier is required to be appointed for the development - provide\nthe principal certifier with written evidence of the payment and the amount paid.","stage":"before_cc","stage_basis":"heading","page":13},{"label":"22","code":null,"number":"22","title":"On Site Detention","text":"The submitted stormwater plan has been assessed as a concept plan only. Final detailed\nplans of the drainage system, prepared by a suitably qualified professional engineer\nspecialising in hydraulic engineering, must be submitted for approval by the Principal\nCertifier with the Construction Certificate.\nAn on-site detention (OSD) facility must be designed and approved by a suitably qualified\nprofessional engineer who specialises in Hydraulic Engineering. The design must include\nthe computations of the inlet and outlet hydrographs and stage/storage relationships of\nthe proposed OSD using the following design parameters:\n(a) Peak flow rates from the site are to be restricted to a permissible site discharge (PSD)\nequivalent to the discharge when assuming the site contained a single dwelling,\ngarage, lawn and garden.\n(b) at Annual Recurrence Intervals for 2 years, 10 years and 100 years.\nThe OSD facility must be designed to meet all legislated safety requirements and\nchildproof safety fencing around the facility must be provided where the OSD facility is\nopen or above ground when the design peak storage depth is greater than 300mm. A\ndurable metal plate or similar sign must be placed at the OSD facility and must bear the\nwords:\n“BEWARE: This is an on -side detention basin/tank for rainwater which could overflow\nduring heavy storms.”\nFull details must accompany the application for the Construction Certificate.","stage":"before_cc","stage_basis":"heading","page":13},{"label":"23","code":null,"number":"23","title":"General Heritage","text":"(a) The proposed works must be carried out in a manner that minimises demolition,\nalterations, and new penetrations or fixings to the significant fabric of the existing\nbuilding which is listed as a Heritage Item.\n(b) The fabric and features to be retained by the proposal must be properly protected\nduring the process of demolition and construction.\n(c) Any protection and conservation measures are to be followed as specified in the\nSchedule of Conservation Works document dated December 2024. All conservation\nand adaption works must be in accordance with the Articles of the Australian\nICOMOS Burra Charter 1999.\n(d) New services must be surface mounted rather than chased -in to existing walls to\nminimise impact on heritage fabric.\n(e) Appropriately qualified tradesperson who are skilled in traditional building and\nengineering trades must be commissioned to carry out the proposed scope of works.\n(f) The new windows and doors proposed to the heritage item must match the original\nmaterial and profile.\n(g) Any original masonry or brickwork to the heritage item must not be rendered,\npainted or coated.\n(h) Sandblasting to remove paint from brick or stone must not be undertaken on a\nheritage item or contributory building in a Heritage Conservation Area.\n(i) Original driveways and footpath crossings must not be relocated.\n(j) Original or early garden layouts that contribute to the streetscape or to the\nsignificance of the heritage item must be protected and not to be altered.\n(k) Modern technologies must not be built or installed higher than the main ridge line\nof a building that is a heritage item (or within a heritage conservation area).\nInfrastructure, such as water heaters, antenna’s, solar panels, skylights/skytubes,\nair-condi\ntioning infrastructure and other similar types of building service\nparaphernalia must be located in such a way that they are not readily interpretable\nvisible from the Public Domain. The location and installation of such services must\nbe conducted in a way where heritage significant fabric is unaffected.\n(l) Original fencing styles and materials must be repaired and retained.\n(m) Non-original materials of existing contributory buildings in Conversation areas that\nare being replaced must be replaced with material that matches the original material\nas closely as possible.\n(n) Original door and window joinery visible from the Public Domain is to be conserved.\nReason: To ensure the protection and preservation of Heritage items and Heritage\nConservation Area.","stage":"before_cc","stage_basis":"heading","page":14},{"label":"24","code":null,"number":"24","title":"Detailed Stormwater Design","text":"The submitted stormwater plan has been assessed as a concept plan only. A detailed\ndrainage design supported by a catchment area plan and drainage calculations (including\na Hydraulic Grade Line Analysis) in accordance with Council’s Stormwater Management\nCode must be submitted to and approved by the Principal Certifier with the Construction\nCertificate Application..","stage":"before_cc","stage_basis":"heading","page":15},{"label":"25","code":null,"number":"25","title":"Erosion and sediment control plan","text":"Before the issue of a construction certificate an erosion and sediment control plan must\nbe prepared by a suitably qualified person in accordance with the following documents\nand provided to the certifying authority.\na) Council’s relevant development control plan,\nb) the guidelines set out in the NSW Department of Housing manual ‘Managing Urban\nStormwater: Soils and Construction Certificate’ (the Blue Book) (as amended from\ntime to time), and\nc) the ‘Guidelines for Erosion and Sediment Control on Building Sites’ (Department of\nPlanning, Housing and Infrastructure)\n(dated 2024, as amended from time to time)","stage":"before_cc","stage_basis":"heading","page":15},{"label":"26","code":null,"number":"26","title":"Dial Before Your Dig","text":"The applicant must contact Home | Before You Dig Australia (BYDA) to obtain a Service\nDiagram prior to the issuing of the Construction Certificate. The sequence number\nobtained from “Dial Before You Dig” must be forwarded to Council’s Engineers for their\nrecords.","stage":"before_cc","stage_basis":"heading","page":15},{"label":"27","code":null,"number":"27","title":"Construction Site Management Plan","text":"Before the issue of a construction certificate, a construction site management plan\nmust be prepared, and provided to Certifying Authority The plan must include the\nfollowing matters:\na) The location and materials for protective fencing and hoardings on the perimeter\nof the site;\nb) Provisions for public safety;\nc) Pedestrian and vehicular site access points and construction activity zones;\nd) Details of construction traffic management including:\ni) Proposed truck movements to and from the site;\nii) Estimated frequency of truck movements; and\niii) Measures to ensure pedestrian safety near the site;\ne) Details of bulk earthworks to be carried out;\nf) The location of site storage areas and sheds;\ng) The equipment used to carry out works;\nh) The location of a garbage container with a tight-fitting lid;\ni) Dust, noise and vibration control measures;\nj) The location of temporary toilets;\nk) The protective measures for the preservation of trees on-site and in adjoining\npublic areas including measures in accordance with:\ni) AS 4970 - Protection of trees on development sites;\nii) An applicable Development Control Plan;\niii) An arborist’s report approved as part of this consent\nA copy of the construction site management plan must be kept on-site at all times while\nwork is being carried out","stage":"before_cc","stage_basis":"heading","page":15},{"label":"28","code":null,"number":"28","title":"Off Street Parking - Compliance with AS2890","text":"All driveways, access ramps, vehicular crossings and car parking spaces must be designed\nand constructed in accordance with the current version of Australian Standards, AS\n2890.1 (for car parking facilities), AS 2890.6 (parking for people with disabilities) and AS\n2890.2 (for commercial vehicle facilities).","stage":"before_cc","stage_basis":"heading","page":16},{"label":"29","code":null,"number":"29","title":"Car parking details","text":"Before the issue of the relevant construction certificate, written evidence prepared by a\nsuitably qualified engineer must be obtained that demonstrates, to the certifier’s\nsatisfaction, the plans for parking facilities comply with the relevant parts of AS 2890.1\nParking Facilities - Off-Street Carparking and council’s relevant development control\nplan (in force as at the date of determination of this consent).","stage":"before_cc","stage_basis":"heading","page":16},{"label":"30","code":null,"number":"30","title":"Tree Removal/Pruning Prohibited","text":"The removal or pruning (branches or roots) of any trees on the subject property\n(excluding those approved for removal in these conditions or species on Council’s\nexempt species list), Council’s public footway, public reserves or on neighbouring\nproperties must not be undertaken other than in accordance with the express provisions\nof this consent.","stage":"before_cc","stage_basis":"heading","page":16},{"label":"31","code":null,"number":"31","title":"Tree Protection and Retention","text":"The following trees are to be protected throughout the course of all demolition and\nconstruction works. Tree protection is to be in place prior to commencement of demolition\nworks.\nTree\nNo.\nTree Species Location of Tree TPZ\nT1 Lophostemon confertus Exeter Rd Street Tree 4.68m\nT2 Lophostemon confertus Exeter Rd Street Tree 7.92m\nT3 Schinus molle Exeter Rd setback 6.48m\nT4 Melaleuca salicina Exeter Rd setback 5.52m\nT5 Lagerstroemia indica Exeter Rd setback 2.87m\nT6 Cupressus torulosa 6-8 Exeter Rd 3.6m\nT7 Corymbia maculata 6-8 Exeter Rd 6m\nT8 Murraya paniculata Henley Rd setback 1.89m\nT9 Plumeria sp. Henley Rd setback 3.1m\nT10 Lophostemon confertus Henley Rd Street Tree 7.32m\nT11 Lophostemon confertus Henley Rd Street Tree 7.08m\nT13 Ligustrum lucidum 6-8 Exeter Rd 4.5m\nT14 Celtis sinensis 6-8 Exeter Rd 2.76m\nA project arborist (min. Qualification AQF5) is to be engaged throughout the demolition\nand construction process.\nThe Project Arborist must be present on -site during the stages of construction when\nworks are being undertaken that could impact on the tree canopy or root zone within\nthe Tree Protection Zone to implement the tree protection measures as required.\nNo services shall be installed within the Tree Protection Zone of the tree unless\napproved by Council. Tree protection fencing shall be kept in place during demolition,\nconstruction and also have a sign displaying ‘Tree Protection Zone’ attached to the\nfence and must also include the name and contact details of the Project Arborist.\nWhere the Tree Protection Zone of trees on site or adjoining sites become compromised\nby any excavation works, the Project Arborist shall be consulted to establish the position\nof any major roots and determine the necessary measures to protect these roots. The\nrecommendations of the Project Arborist shall be submitted to Council prior to any\nfurther demolition or construction works taking place","stage":"before_cc","stage_basis":"heading","page":17},{"label":"32","code":null,"number":"32","title":"Landscape Plan Amendments","text":"Prior to issue of the Construction Certificate the proposed OSD basin and associated\npits and pipes shall be amended such that works are outside the SRZ of trees on the\nneighbouring property, 6-8 Exeter Road. Construction of the proposed boundary wall\nthroughout tree TPZ areas shall be undertaken under the supervision of the project\narborist such that roots of the neighbouring trees are spanned (ie: pier and beam typ e\nconstruction). The project arborist is to provide certification that the works have been\nundertaken accordingly.","stage":"before_cc","stage_basis":"heading","page":17},{"label":"33","code":null,"number":"33","title":"Street and Reserve Tree Protection and Retention","text":"A protective fence consisting of a fully supported chainmesh fence 1.8 metres height x\n2 metres clear of the base of the tree at any one point must be erected around the\nnominated street trees in front of 8 -10 Exeter Road and any trees in adjacent reserves\nand parks if applicable, unless otherwise specified in AS4970 -2009. The fence is to\nextend up to the back of the kerb and to the edge of the footpath. No services shall be\ninstalled within the Tree Protection Zone of the tree unless approved by Council. Tree\nprotection fencing shall be kept in place during demolition, construction and also have\na sign displaying ‘Tree Protection Zone’ attached to the fence and must also include the\nname and contact details of the Project Arborist.\nNo soil, fill, building materials or waste should be placed or disposed of within the\nprotection area.\nTree No. Tree Species Location of Tree\nT1 Lophostemon confertus Exeter Rd Street Tree\nT2 Lophostemon confertus Exeter Rd Street Tree\nT10 Lophostemon confertus Henley Rd Street Tree\nT11 Lophostemon confertus Henley Rd Street Tree\nShould replacement or repair of the public footpath or vehicle crossing within the Tree\nProtection Zone area of a street tree be required, Council’s Urban Forest Supervisor is\nto be notified (with minimum 24hrs notice) of the intent to undertake the works and is\nto attend a site inspection after the existing footpath has been lifted but prior to any\npreparation works for laying of the new path. No street tree roots are to be cut without\nthe Approval of Council. Failure to comply with this condition may result in the\nforfeiting of the Tree Bond should the street tree’s health or structure be\ncompromised.","stage":"before_work","stage_basis":"heading","page":18},{"label":"34","code":null,"number":"34","title":"Demolition & Asbestos","text":"The demolition work must comply with the provisions of Australian Standard\nAS2601:2001 - Demolition of Structures, NSW Work Health & Safety Act 2011 and the\nNSW Work Health & Safety Regulation 2011 . The work plans required by AS2601:2001\nmust be accompanied by a written statement by a suitably qualified person that the\nproposals contained in the work plan comply with the safety requirements of the\nStandard. The work plans and the safety statement must be submitted to the Principal\nCertifier prior to the commencement of works.\nFor demolition work which involves the removal of asbestos, the asbestos removal work\nmust be carried out by a licensed asbestos removalist who is licensed to carry out the\nwork in accordance with the NSW Work Health & Safety Act 2011 and the NSW\nWork\nHealth & Safety Regulation 2011 unless specified in the Act or Regulation that a license\nis not required.\nAll demolition work including the removal of asbestos, must be undertaken in\naccordance with the Demolition Code of Practice (NSW Work Cover July 2015)","stage":"before_work","stage_basis":"heading","page":18},{"label":"35","code":null,"number":"35","title":"Use of Heritage Consultant","text":"A suitably qualified heritage consultant experienced in conserving buildings of\nsignificance must be commissioned to work with the consultant team throughout the\ndesign development, contract documentation and construction stages of the project.\nThe heritage consultant must be involved in the resolution of all matters where existing\nsignificant fabric and spaces are to be subject to pr\neservation, restoration,\nreconstruction, adaptive reuse, recording and demolition. The heritage consultant must\nbe provided with full access to the site and authorised by the applicant to respond\ndirectly to Council where information or clarification is required regarding the resolution\nof heritage issues throughout the project.\nEvidence and details of the above commission on the above terms must be provided to\nCouncil’s Heritage Planner prior to commencement of work on site. The heritage\nconsultant must sign off the completed project and submit a final report to Council’s\nHeritage Planner specifying how the heritage conditions are satisfied prior to the issue\nof any Occupation Certificate or the commencement of the use, whichever occurs first.","stage":"before_work","stage_basis":"heading","page":19},{"label":"36","code":null,"number":"36","title":"Materials for Making Good","text":"New materials for making good and repairs must match the existing in terms of colours,\nfinishes, sizes, profile and properties.","stage":"before_work","stage_basis":"heading","page":19},{"label":"37","code":null,"number":"37","title":"Erosion and sediment controls in place","text":"Before any site work commences, the principal certifier, must be satisfied the erosion\nand sediment controls in the erosion and sediment control plan which was provided to\nprincipal certifier are in place. These controls must remain in place until any bare earth\nhas been restabilised in accordance with the\nerosion and sediment control plan.","stage":"before_work","stage_basis":"heading","page":19},{"label":"38","code":null,"number":"38","title":"Dilapidation report","text":"Before any site work commences, a dilapidation report must be prepared by a suitably\nqualified engineer detailing the structural condition of adjoining buildings, structures or\nworks and public land, to the satisfaction of the certifying authority.\nWhere access has not been granted to any adjoining properties to prepare the\ndilapidation report, the report must be based on a survey of what can be observed\nexternally and demonstrate, in writing, to the satisfaction of the certifying authority\nthat all reasonable steps were taken to obtain access to the adjoining properties.","stage":"before_work","stage_basis":"heading","page":19},{"label":"39","code":null,"number":"39","title":"Stormwater Plan Amendment","text":"The size of the orifice must be calculated and shown on the stormwater plans prior to\nthe release of construction certificate.\nReason: To enable assessment of maximum discharge from site","stage":"during_work","stage_basis":"heading","page":20},{"label":"40","code":null,"number":"40","title":"Tree protection measures","text":"Before any site work commences, the principal certifier, or council where a principal\ncertifier is not required, must be satisfied the measures for tree protection detailed in\nthe construction site management plan are in place.","stage":"during_work","stage_basis":"heading","page":20},{"label":"41","code":null,"number":"41","title":"Hours of work","text":"Site work must only be carried out between the following times -\nFor building construction and delivery of machinery and materials from 7:00am to\n5:00pm on Monday to Saturday (excluding Public Holidays)\nFor demolition, excavation and/or construction works that involve heavy machinery,\nnoisy trades, or the like from 7:00am to 5:00pm on Monday to Friday (excluding Public\nHolidays)\nSite work is not to be carried out outside of these times except where there is an\nemergency, or for urgent work directed by a police officer or a public authority.","stage":"during_work","stage_basis":"heading","page":20},{"label":"42","code":null,"number":"42","title":"Procedure for critical stage inspections","text":"While building work is being carried out, the work must not continue after each critical\nstage inspection unless the principal certifier is satisfied the work may proceed in\naccordance with this consent and the relevant construction certificate.","stage":"during_work","stage_basis":"heading","page":20},{"label":"43","code":null,"number":"43","title":"Waste management","text":"While site work is being carried out:\na) all waste management must be undertaken in accordance with the waste\nmanagement plan, and\nb) upon disposal of waste, records of the disposal must be compiled and provided to\nthe Certifier, or Council where a certifier is not required, detailing the following:\ni) The contact details of the person(s) who removed the waste\nii) The waste carrier vehicle registration\niii) The date and time of waste collection\niv) A description of the waste (type of waste and estimated quantity) and\nwhether the waste is to be reused, recycled or go to landfill\nv) The address of the disposal location(s) where the waste was taken\nvi) The corresponding tip docket/receipt from the site(s) to which the waste is\ntransferred, noting date and time of delivery, description (type and\nquantity) of waste.\nIf waste has been removed from the site under an EPA Resource Recovery Order or\nExemption, records in relation to that Order or Exemption must be maintained and\nprovided to the principal certifier and council.","stage":"during_work","stage_basis":"heading","page":21},{"label":"44","code":null,"number":"44","title":"Discovery of relics and Aboriginal objects","text":"While site work is being carried out, if a person reasonably suspects a relic of Aboriginal\nobject is discovered:\na) the work in the area of the discovery must cease immediately;\nb) the following must be notified\ni) for a relic - the Heritage Council; or\nii) for an Aboriginal object - the person who is the authority for the protection of\nAboriginal objects and Aboriginal places in New South Wales under the\nNational Parks and Wildlife Act 1974, section 85.\nSite work may recommence at a time confirmed in writing by: for a relic - the Heritage\nCouncil; or for an Aboriginal object - the person who is the authority for the protection\nof Aboriginal objects and Aboriginal places in New South Wales under the National\nParks and Wildlife Act 1974, section 85.","stage":"during_work","stage_basis":"heading","page":21},{"label":"45","code":null,"number":"45","title":"Salvage, Reuse and Recycling of Traditional Building Materials","text":"Stone, bricks, roof tiles, joinery and decorative architectural elements which are to be\ndemolished, including stairs, windows and doors, chimney pieces and ceiling roses must\nbe salvaged and, where possible, reused on the project.\nSalvaged building materials surplus to the project must either be stored on site for future\nreuse or transferred to an established second building material dealer for recycling.","stage":"during_work","stage_basis":"heading","page":21},{"label":"46","code":null,"number":"46","title":"Responsibility for changes to public infrastructure","text":"While site work is being carried out, any costs incurred as a result of the approved\nremoval, relocation or reconstruction of infrastructure (including ramps, footpaths, kerb\nand gutter, light poles, kerb inlet pits, service provider pits, street trees or any other\ninfrastructure in the street footpath area) must be paid as directed by the consent\nauthority.","stage":"before_oc","stage_basis":"heading","page":22},{"label":"47","code":null,"number":"47","title":"Construction Management Plan","text":"The builder must ensure that the approved Construction Traffic Management Plan is to\nbe strictly complied with and kept on site at all times during construction works.","stage":"before_oc","stage_basis":"heading","page":22},{"label":"48","code":null,"number":"48","title":"Tree protection during work","text":"While site work is being carried out, all required tree protection measures must be\nmaintained in good condition in accordance with:\na) the construction site management plan required under this consent,\nb) the relevant requirements of AS 4970 Protection of trees on development sites,\nc) any arborist’s report approved under this consent.\nThis includes maintaining adequate soil grades and ensuring all machinery, builders\nrefuse, spoil and materials remain outside tree protection zones.","stage":"before_oc","stage_basis":"heading","page":22},{"label":"49","code":null,"number":"49","title":"BASIX Certificate","text":"All energy efficiency measures as detailed in the approved BASIX Certificate in the plans\napproved with the Development Consent, must be implemented before the issue of any\nOccupation Certificate.","stage":"before_oc","stage_basis":"heading","page":22},{"label":"50","code":null,"number":"50","title":"Release of securities","text":"When Council receives an occupation certificate an application may be lodged to release\nthe securities held in accordance with Council’s Policies.","stage":"before_oc","stage_basis":"heading","page":22},{"label":"51","code":null,"number":"51","title":"Restriction to User and Positive Covenant for Stormwater Management System","text":"Prior to the issue of any Occupation Certificate, the applicant must register a Positive\nCovenant and a Restriction as to User under section 88E and or section 88B of the\nConveyancing Act as appropriate in favour of Council, ensuring the ongoing retention,\nmaintenance and operation of the stormwater facility (on -site detention, pump -out,\ncharged lines, water sensitive urban design, surface flow path, finished pavement and\nground levels etc.).\nWhere any drainage line or service conduit is to traverse any property other than that\nwhich it serves, an appropriate easement will be required. In this case, the applicant\nmust register an easement no less than 1200mm wide over the proposed drainage lin e\nor service concurrently with any subdivision registration.\nThe wording on the 88E and or 88B Instrument is to make reference to the Council file\nwhere the Construction plans and the Work As Executed (as built), plans are held. Typical\nwording can be obtained from Council's Specification for the Management of\nStormwater document.","stage":"before_oc","stage_basis":"heading","page":22},{"label":"52","code":null,"number":"52","title":"Maintenance Schedule - On-site Stormwater Management","text":"A Maintenance Schedule for the proposed on -site stormwater management measures\nmust be prepared by a suitably qualified professional hydraulic engineer and submitted\nto Council. The Maintenance Schedule must outline the required maintenance works,\nhow and when these will be done and who will be carrying out these maintenance works.","stage":"before_oc","stage_basis":"heading","page":23},{"label":"53","code":null,"number":"53","title":"Post-construction dilapidation report","text":"Before the issue of an occupation certificate a post- construction dilapidation report\nmust be prepared by a suitably qualified engineer, to the satisfaction of the certifying\nauthority detailing whether:\na) after comparing the pre-construction dilapidation report to the post-construction\ndilapidation report required under this condition, there has been any structural\ndamage to any adjoining buildings; and\nb) where there has been structural damage to any adjoining buildings, that it is a\nresult of the work approved under this development consent, and\na copy of the post-construction dilapidation report must be provided to council (where\ncouncil is not the principal certifier or a principal certifier is not required) and to the\nrelevant adjoining property owner(s).","stage":"before_oc","stage_basis":"heading","page":23},{"label":"54","code":null,"number":"54","title":"Repair of infrastructure","text":"","stage":"before_oc","stage_basis":"heading","page":24},{"label":"55","code":null,"number":"55","title":"Works-as-executed plans and any other documentary evidence","text":"Before the issue of the relevant occupation certificate, works-as-executed plans, any\ncompliance certificates and any other evidence confirming the following completed\nworks must be submitted to the satisfaction of the principal certifier:\na) All stormwater drainage systems and storage systems, and\nb) to council with the Occupation Certificate","stage":"before_oc","stage_basis":"heading","page":24},{"label":"56","code":null,"number":"56","title":"Fire Safety Before Occupation or Use","text":"In accordance with Clause 41 of the Environmental Planning and Assessment\n(Development Certification and Fire Safety) Regulation 2021 - NSW Legislation , on\ncompletion of building works and prior to the issue of any Occupation Certificate, the\nowner must cause the issue of a Final Fire Safety Certificate in accordance with Clause\n83 of that Regulation. The Fire Safety Certificate must be in the form or to the effect of\nClause 86 of the Environmental Planning and Assessment (Development Certification\nand Fire Safety) Regulation 2021 - NSW Legislation. Additionally, in relation to each\nessential fire or other safety measure implemented in the building or on the land on\nwhich the building is situated, such a Certificate must state:\n(a) That the measure has been assessed by a person (chosen by the owner of the\nbuilding) who is properly qualified to do so.\n(b) That as at the date of the assessment the measure was found to be capable of\nfunctioning at a standard not less than that required by the Schedule.\nA copy of the certificate must be given by the applicant to the Commissioner of Fire &\nRescue NSW and a further copy is to be displayed in a frame and fixed to a wall inside\nthe building's main entrance.","stage":"before_oc","stage_basis":"heading","page":24},{"label":"57","code":null,"number":"57","title":"Completion of Landscape Works and Tree Works","text":"Before the issue of an Occupation Certificate, the principal certifier must be satisfied all\nlandscape and tree-works have been completed in accordance with approved plans\nand documents and any relevant conditions of this consent.","stage":"ongoing","stage_basis":"heading","page":25},{"label":"58","code":null,"number":"58","title":"Maintenance of Landscaping","text":"All trees and plants forming part of the landscaping must be maintained. Maintenance\nincludes watering, weeding, removal of rubbish from tree bases, fertilising, pest and\ndisease control, replacement of dead or drying plants and any other operations required\nto maintain healthy trees, plants and turfed areas.","stage":"ongoing","stage_basis":"heading","page":25},{"label":"59","code":null,"number":"59","title":"Noise Control","text":"The use of the premises must not give rise to the transmission of offensive noise to any\nplace of different occupancy. Offensive noise is defined in the Protection of the\nEnvironment Operations Act 1997 (as amended).","stage":"ongoing","stage_basis":"heading","page":25},{"label":"60","code":null,"number":"60","title":"Storage of Waste","text":"Activities including storing of waste outside of the building must not occur with the\nexception of waste receptacles.","stage":"ongoing","stage_basis":"heading","page":25},{"label":"61","code":null,"number":"61","title":"Standing Vehicles on Public Roads","text":"Motor vehicles awaiting repair or under repair, or waiting delivery, must not be stored,\nparked, or otherwise permitted to stand in a public street. All such vehicles must be\naccommodated within the premises.","stage":"ongoing","stage_basis":"heading","page":25},{"label":"62","code":null,"number":"62","title":"Loading & Unloading of Vehicles","text":"All loading and unloading of vehicles in relation to the use of the premises must take\nplace wholly within a dedicated loading dock area.","stage":"ongoing","stage_basis":"heading","page":25},{"label":"63","code":null,"number":"63","title":"Entering and Exiting of Vehicles","text":"All vehicles must enter and exit the premises in a forward direction.","stage":"ongoing","stage_basis":"heading","page":25}]});
